use core::sync::atomic::{AtomicU32 as A,Ordering as O};fn main(){let a=A::new(0);check(a.fetch_or(4294967295,O::Relaxed)==0);check(a.load(O::Relaxed)==4294967295);check(a.fetch_and(0,O::Relaxed)==4294967295);check(a.load(O::Relaxed)==0);check(a.fetch_xor(4294967295,O::Relaxed)==0);check(a.load(O::Relaxed)==4294967295);check(a.fetch_nand(4294967295,O::Relaxed)==4294967295);check(a.load(O::Relaxed)==0);}
